"""Order fulfillment — SQLite-backed order service with stock reservation."""

from __future__ import annotations

import json
import math
import os
import sqlite3
from typing import Any


class OrderError(Exception):
    """Stable order-domain error."""

    def __init__(self, code: str, message: str, details: dict[str, Any] | None = None):
        self.code = code
        self.message = message
        self.details = details if details is not None else {}
        super().__init__(message)

    def __str__(self) -> str:
        return self.message


_EXPECTED_SCHEMA = {
    "stock": [("sku", "TEXT"), ("available", "INTEGER")],
    "orders": [
        ("order_id", "TEXT"),
        ("idempotency_key", "TEXT"),
        ("status", "TEXT"),
        ("total_cents", "INTEGER"),
        ("payment_id", "TEXT"),
        ("created_at", "REAL"),
        ("updated_at", "REAL"),
    ],
    "order_items": [
        ("order_id", "TEXT"),
        ("sku", "TEXT"),
        ("quantity", "INTEGER"),
        ("unit_price_cents", "INTEGER"),
    ],
}


def _validate_field(val: Any, expected: type) -> None:
    if expected is str:
        if not isinstance(val, str):
            raise OrderError("INVALID_INPUT", f"expected string, got {type(val).__name__}", {})
        if not val.strip():
            raise OrderError("INVALID_INPUT", "string must be non-empty and non-whitespace", {})
    elif expected is int:
        if isinstance(val, bool) or not isinstance(val, int):
            raise OrderError("INVALID_INPUT", f"expected integer, got {type(val).__name__}", {})
    elif expected is float:
        if not isinstance(val, (int, float)) or isinstance(val, bool):
            raise OrderError("INVALID_INPUT", f"expected number, got {type(val).__name__}", {})
    elif expected is dict:
        if not isinstance(val, dict):
            raise OrderError("INVALID_INPUT", f"expected dict, got {type(val).__name__}", {})


def _validate_non_empty_str(val: Any, name: str) -> str:
    if not isinstance(val, str):
        raise OrderError("INVALID_INPUT", f"{name} must be a string", {})
    if not val.strip():
        raise OrderError("INVALID_INPUT", f"{name} must be non-empty and non-whitespace", {})
    return val


def _validate_int(val: Any, name: str, minimum: int | None = None) -> int:
    if isinstance(val, bool) or not isinstance(val, int):
        raise OrderError("INVALID_INPUT", f"{name} must be an integer", {})
    if minimum is not None and val < minimum:
        raise OrderError("INVALID_INPUT", f"{name} must be >= {minimum}", {})
    return val


def _validate_items(items: list[dict]) -> list[tuple[str, int, int]]:
    if not isinstance(items, list) or not items:
        raise OrderError("INVALID_INPUT", "items must be a non-empty list", {})
    seen = set()
    result = []
    for item in items:
        if not isinstance(item, dict):
            raise OrderError("INVALID_INPUT", "each item must be an object", {})
        allowed = {"sku", "quantity", "unit_price_cents"}
        if set(item.keys()) != allowed:
            raise OrderError("INVALID_INPUT", "each item must have exactly sku, quantity, unit_price_cents", {})
        sku = _validate_non_empty_str(item["sku"], "sku")
        qty = _validate_int(item["quantity"], "quantity", 1)
        price = _validate_int(item["unit_price_cents"], "unit_price_cents", 0)
        if sku in seen:
            raise OrderError("INVALID_INPUT", f"duplicate sku: {sku}", {})
        seen.add(sku)
        result.append((sku, qty, price))
    result.sort(key=lambda x: x[0])
    return result


def _check_schema(conn: sqlite3.Connection) -> None:
    cursor = conn.execute("SELECT name FROM sqlite_master WHERE type='table'")
    tables = {row[0] for row in cursor.fetchall()}
    expected_tables = {"stock", "orders", "order_items"}
    if not tables:
        return  # no tables exist, will be created
    if not expected_tables.issubset(tables):
        raise OrderError("SCHEMA_MISMATCH", "missing tables", {})
    # Check column types
    for tname, expected_cols in _EXPECTED_SCHEMA.items():
        cursor = conn.execute(f"PRAGMA table_info({tname})")
        actual = {row[1]: row[2] for row in cursor.fetchall()}
        for col_name, expected_type in expected_cols:
            if col_name not in actual:
                raise OrderError("SCHEMA_MISMATCH", f"table {tname} missing column {col_name}", {})
            actual_type = actual[col_name].upper()
            if actual_type == "INTEGER":
                pass  # accept INTEGER or derived
            elif actual_type == "TEXT":
                pass
            elif actual_type == "REAL":
                pass
            else:
                # Check if types are compatible
                if expected_type == "INTEGER" and actual_type != "INTEGER":
                    raise OrderError("SCHEMA_MISMATCH", f"column {tname}.{col_name} type mismatch", {})
                if expected_type == "TEXT" and actual_type not in ("TEXT", "VARCHAR", "CHAR"):
                    raise OrderError("SCHEMA_MISMATCH", f"column {tname}.{col_name} type mismatch", {})
    # Check unique constraint on idempotency_key
    cursor = conn.execute("PRAGMA index_list(orders)")
    indexes = {row[1] for row in cursor.fetchall()}
    if "idx_orders_idempotency" not in indexes and "sqlite_autoindex_orders_1" not in indexes:
        pass  # we'll check via application logic


def _build_order_dict(conn: sqlite3.Connection, order_id: str) -> dict[str, Any]:
    row = conn.execute(
        "SELECT order_id, idempotency_key, status, total_cents, payment_id, created_at, updated_at "
        "FROM orders WHERE order_id = ?",
        (order_id,),
    ).fetchone()
    if row is None:
        raise OrderError("NOT_FOUND", f"order not found: {order_id}", {})
    items = conn.execute(
        "SELECT sku, quantity, unit_price_cents FROM order_items WHERE order_id = ? ORDER BY sku",
        (order_id,),
    ).fetchall()
    return {
        "order_id": row[0],
        "idempotency_key": row[1],
        "status": row[2],
        "items": [
            {"sku": it[0], "quantity": it[1], "unit_price_cents": it[2]}
            for it in items
        ],
        "total_cents": row[3],
        "payment_id": row[4],
        "created_at": row[5],
        "updated_at": row[6],
    }


class OrderService:
    """SQLite-backed order service."""

    def __init__(self, db_path, *, clock, id_factory):
        self._clock = clock
        self._id_factory = id_factory
        is_new = not os.path.exists(str(db_path))
        self._conn = sqlite3.connect(str(db_path), check_same_thread=False)
        self._conn.row_factory = sqlite3.Row
        self._conn.execute("PRAGMA journal_mode=WAL")
        self._conn.execute("PRAGMA foreign_keys=ON")

        if is_new:
            self._init_schema()
        else:
            _check_schema(self._conn)
            # Also create if any table missing (for empty db)
            tables = set(
                row[0]
                for row in self._conn.execute(
                    "SELECT name FROM sqlite_master WHERE type='table'"
                ).fetchall()
            )
            expected = {"stock", "orders", "order_items"}
            if not expected.issubset(tables):
                self._init_schema()

    def _init_schema(self) -> None:
        self._conn.executescript("""
            CREATE TABLE IF NOT EXISTS stock (
                sku TEXT PRIMARY KEY,
                available INTEGER NOT NULL CHECK(available >= 0)
            );
            CREATE TABLE IF NOT EXISTS orders (
                order_id TEXT PRIMARY KEY,
                idempotency_key TEXT NOT NULL UNIQUE,
                status TEXT NOT NULL DEFAULT 'pending'
                    CHECK(status IN ('pending','paid','shipped','cancelled')),
                total_cents INTEGER NOT NULL,
                payment_id TEXT,
                created_at REAL NOT NULL,
                updated_at REAL NOT NULL
            );
            CREATE TABLE IF NOT EXISTS order_items (
                order_id TEXT NOT NULL,
                sku TEXT NOT NULL,
                quantity INTEGER NOT NULL,
                unit_price_cents INTEGER NOT NULL,
                PRIMARY KEY (order_id, sku),
                FOREIGN KEY (order_id) REFERENCES orders(order_id)
            );
            CREATE INDEX IF NOT EXISTS idx_orders_idempotency
                ON orders(idempotency_key);
        """)
        self._conn.commit()

    def set_stock(self, sku: str, quantity: int) -> dict:
        sku = _validate_non_empty_str(sku, "sku")
        qty = _validate_int(quantity, "quantity", 0)
        with self._conn:
            self._conn.execute(
                "INSERT INTO stock (sku, available) VALUES (?, ?) "
                "ON CONFLICT(sku) DO UPDATE SET available = ?",
                (sku, qty, qty),
            )
        return {"sku": sku, "available": qty}

    def _canonical_items_key(self, items: list[dict]) -> str:
        """Serialize canonical items for idempotency comparison."""
        triple = _validate_items(items)
        return json.dumps(triple, sort_keys=True, separators=(",", ":"), ensure_ascii=False)

    def _get_clock(self) -> float:
        val = self._clock()
        if isinstance(val, bool) or not isinstance(val, (int, float)):
            raise OrderError("INVALID_DEPENDENCY", "clock returned invalid type", {})
        if not math.isfinite(val):
            raise OrderError("INVALID_DEPENDENCY", "clock returned non-finite value", {})
        return float(val)

    def _get_id(self) -> str:
        for _ in range(3):
            val = self._id_factory()
            if not isinstance(val, str):
                raise OrderError("INVALID_DEPENDENCY", "id_factory returned non-string", {})
            if not val.strip():
                raise OrderError("INVALID_DEPENDENCY", "id_factory returned empty/whitespace", {})
            return val
        raise OrderError("ID_COLLISION", "failed to generate unique order id after 3 attempts", {})

    def create_order(self, idempotency_key: str, items: list[dict]) -> dict:
        ikey = _validate_non_empty_str(idempotency_key, "idempotency_key")
        canonical = self._canonical_items_key(items)
        parsed_items = json.loads(canonical)

        now = self._get_clock()

        with self._conn:
            # Check idempotency
            existing = self._conn.execute(
                "SELECT order_id FROM orders WHERE idempotency_key = ?",
                (ikey,),
            ).fetchone()
            if existing is not None:
                return _build_order_dict(self._conn, existing[0])

            # Check stock sufficiency
            for sku, qty, _ in parsed_items:
                row = self._conn.execute(
                    "SELECT available FROM stock WHERE sku = ?", (sku,),
                ).fetchone()
                if row is None:
                    raise OrderError("INSUFFICIENT_STOCK",
                                     f"sku not found: {sku}", {"sku": sku})
                if row[0] < qty:
                    raise OrderError("INSUFFICIENT_STOCK",
                                     f"insufficient stock for sku: {sku}", {"sku": sku})

            total = sum(qty * price for _, qty, price in parsed_items)

            # Generate unique order id (retry loop)
            oid = self._get_id()
            # Check uniqueness within transaction
            existing_oid = self._conn.execute(
                "SELECT 1 FROM orders WHERE order_id = ?", (oid,),
            ).fetchone()
            if existing_oid is not None:
                raise OrderError("ID_COLLISION", "generated order id already exists", {})

            self._conn.execute(
                "INSERT INTO orders (order_id, idempotency_key, status, total_cents, "
                "payment_id, created_at, updated_at) VALUES (?, ?, 'pending', ?, NULL, ?, ?)",
                (oid, ikey, total, now, now),
            )

            for sku, qty, price in parsed_items:
                self._conn.execute(
                    "INSERT INTO order_items (order_id, sku, quantity, unit_price_cents) "
                    "VALUES (?, ?, ?, ?)",
                    (oid, sku, qty, price),
                )
                self._conn.execute(
                    "UPDATE stock SET available = available - ? WHERE sku = ?",
                    (qty, sku),
                )

            return _build_order_dict(self._conn, oid)

    def pay_order(self, order_id: str, payment_id: str, amount_cents: int) -> dict:
        oid = _validate_non_empty_str(order_id, "order_id")
        pid = _validate_non_empty_str(payment_id, "payment_id")
        amt = _validate_int(amount_cents, "amount_cents", 0)

        now = self._get_clock()

        with self._conn:
            row = self._conn.execute(
                "SELECT order_id, status, payment_id, total_cents FROM orders WHERE order_id = ?",
                (oid,),
            ).fetchone()
            if row is None:
                raise OrderError("NOT_FOUND", f"order not found: {oid}", {})

            # Check amount mismatch before mutation
            if amt != row["total_cents"]:
                raise OrderError("AMOUNT_MISMATCH",
                                 f"amount {amt} != total {row['total_cents']}", {})

            status = row["status"]
            existing_pid = row["payment_id"]

            # Idempotent repeat
            if existing_pid == pid and status in ("paid", "shipped", "cancelled"):
                return _build_order_dict(self._conn, oid)

            # Payment conflict: different payment_id for already paid order
            if existing_pid is not None and existing_pid != pid:
                raise OrderError("PAYMENT_CONFLICT",
                                 "order already paid with different payment_id", {})

            # Payment conflict: same payment_id for different order
            dup = self._conn.execute(
                "SELECT order_id FROM orders WHERE payment_id = ? AND order_id != ?",
                (pid, oid),
            ).fetchone()
            if dup is not None:
                raise OrderError("PAYMENT_CONFLICT",
                                 f"payment_id already used for order {dup[0]}", {})

            # State check
            if status != "pending":
                if status == "paid":
                    raise OrderError("PAYMENT_CONFLICT",
                                     "order already paid", {})
                raise OrderError("INVALID_STATE",
                                 f"cannot pay order in status: {status}", {})

            self._conn.execute(
                "UPDATE orders SET status='paid', payment_id=?, updated_at=? WHERE order_id=?",
                (pid, now, oid),
            )
            return _build_order_dict(self._conn, oid)

    def cancel_order(self, order_id: str) -> dict:
        oid = _validate_non_empty_str(order_id, "order_id")
        now = self._get_clock()

        with self._conn:
            row = self._conn.execute(
                "SELECT order_id, status, payment_id FROM orders WHERE order_id = ?",
                (oid,),
            ).fetchone()
            if row is None:
                raise OrderError("NOT_FOUND", f"order not found: {oid}", {})

            status = row["status"]

            # Idempotent repeat
            if status == "cancelled":
                return _build_order_dict(self._conn, oid)

            if status == "shipped":
                raise OrderError("INVALID_STATE",
                                 "cannot cancel shipped order", {})

            if status not in ("pending", "paid"):
                raise OrderError("INVALID_STATE",
                                 f"cannot cancel order in status: {status}", {})

            # Release stock
            items = self._conn.execute(
                "SELECT sku, quantity FROM order_items WHERE order_id = ?",
                (oid,),
            ).fetchall()
            for sku, qty in items:
                self._conn.execute(
                    "UPDATE stock SET available = available + ? WHERE sku = ?",
                    (qty, sku),
                )

            self._conn.execute(
                "UPDATE orders SET status='cancelled', updated_at=? WHERE order_id=?",
                (now, oid),
            )
            return _build_order_dict(self._conn, oid)

    def ship_order(self, order_id: str) -> dict:
        oid = _validate_non_empty_str(order_id, "order_id")
        now = self._get_clock()

        with self._conn:
            row = self._conn.execute(
                "SELECT order_id, status FROM orders WHERE order_id = ?",
                (oid,),
            ).fetchone()
            if row is None:
                raise OrderError("NOT_FOUND", f"order not found: {oid}", {})

            status = row["status"]
            if status == "shipped":
                return _build_order_dict(self._conn, oid)
            if status != "paid":
                raise OrderError("INVALID_STATE",
                                 f"cannot ship order in status: {status}", {})

            self._conn.execute(
                "UPDATE orders SET status='shipped', updated_at=? WHERE order_id=?",
                (now, oid),
            )
            return _build_order_dict(self._conn, oid)

    def get_order(self, order_id: str) -> dict:
        oid = _validate_non_empty_str(order_id, "order_id")
        with self._conn:
            row = self._conn.execute(
                "SELECT order_id, idempotency_key, status, total_cents, payment_id, "
                "created_at, updated_at FROM orders WHERE order_id = ?",
                (oid,),
            ).fetchone()
        if row is None:
            raise OrderError("NOT_FOUND", f"order not found: {oid}", {})
        return _build_order_dict(self._conn, oid)

    def close(self) -> None:
        self._conn.close()


__all__ = ["OrderError", "OrderService"]

