"""Order fulfillment JSON CLI entry point.

Usage: python -m src.order_fulfillment --db <path> <command>

Commands: stock, create, pay, cancel, ship, get
"""

from __future__ import annotations

import json
import sys
import time
import uuid

from src.order_fulfillment import OrderError, OrderService


_COMMANDS = frozenset({"stock", "create", "pay", "cancel", "ship", "get"})


def _read_input() -> dict:
    line = sys.stdin.readline()
    if not line or not line.strip():
        return {}
    try:
        obj = json.loads(line)
    except json.JSONDecodeError:
        _error_exit("INVALID_INPUT", "invalid JSON on stdin", {})
    if not isinstance(obj, dict):
        _error_exit("INVALID_INPUT", "input must be a JSON object", {})
    return obj


def _success_exit(result) -> None:
    envelope = {"ok": True, "result": result}
    sys.stdout.write(
        json.dumps(envelope, sort_keys=True, separators=(",", ":"), allow_nan=False)
        + "\n"
    )
    sys.stdout.flush()
    sys.exit(0)


def _error_exit(code: str, message: str, details: dict, exit_code: int = 2) -> None:
    envelope = {
        "ok": False,
        "error": {"code": code, "message": message, "details": details},
    }
    sys.stdout.write(
        json.dumps(envelope, sort_keys=True, separators=(",", ":"), allow_nan=False)
        + "\n"
    )
    sys.stdout.flush()
    sys.exit(exit_code)


def main() -> None:
    args = sys.argv[1:]
    if len(args) < 3 or args[0] != "--db":
        _error_exit(
            "INVALID_INPUT",
            "usage: python -m src.order_fulfillment --db <path> <command>",
            {},
        )

    db_path = args[1]
    command = args[2]

    if command not in _COMMANDS:
        _error_exit(
            "INVALID_INPUT",
            f"unknown command: {command}",
            {"valid": sorted(_COMMANDS)},
        )

    inp = _read_input()

    svc = OrderService(db_path, clock=time.time, id_factory=lambda: uuid.uuid4().hex)

    try:
        if command == "stock":
            sku = inp.get("sku")
            qty = inp.get("quantity")
            if sku is None or qty is None:
                _error_exit("INVALID_INPUT", "stock requires sku and quantity", {})
            result = svc.set_stock(sku, qty)
        elif command == "create":
            ikey = inp.get("idempotency_key")
            items = inp.get("items")
            if ikey is None or items is None:
                _error_exit(
                    "INVALID_INPUT", "create requires idempotency_key and items", {}
                )
            result = svc.create_order(ikey, items)
        elif command == "pay":
            oid = inp.get("order_id")
            pid = inp.get("payment_id")
            amt = inp.get("amount_cents")
            if oid is None or pid is None or amt is None:
                _error_exit(
                    "INVALID_INPUT",
                    "pay requires order_id, payment_id, and amount_cents",
                    {},
                )
            result = svc.pay_order(oid, pid, amt)
        elif command == "cancel":
            oid = inp.get("order_id")
            if oid is None:
                _error_exit("INVALID_INPUT", "cancel requires order_id", {})
            result = svc.cancel_order(oid)
        elif command == "ship":
            oid = inp.get("order_id")
            if oid is None:
                _error_exit("INVALID_INPUT", "ship requires order_id", {})
            result = svc.ship_order(oid)
        elif command == "get":
            oid = inp.get("order_id")
            if oid is None:
                _error_exit("INVALID_INPUT", "get requires order_id", {})
            result = svc.get_order(oid)
        else:
            _error_exit("INVALID_INPUT", f"unhandled command: {command}", {})
            return  # unreachable
    except OrderError as exc:
        _error_exit(exc.code, exc.message, exc.details, exit_code=2)
    except Exception:
        # Unhandled internal/storage error
        _error_exit("STORAGE_ERROR", "unexpected storage failure", {}, exit_code=3)
    else:
        _success_exit(result)
    finally:
        try:
            svc.close()
        except Exception:
            pass


if __name__ == "__main__":
    main()

