"""Delivery spool — filesystem-backed outbox with lease-based worker claim."""

from __future__ import annotations

import dataclasses
import hmac
import json
import math
import os
import time
from typing import Any, Callable


@dataclasses.dataclass(frozen=True)
class Limits:
    max_messages: int = 10000
    max_payload_bytes: int = 65536
    max_attempts: int = 5
    lease_seconds: float = 30.0
    retry_delay: float = 10.0


class SpoolError(Exception):
    """Stable spool-domain error."""

    def __init__(self, code: str, message: str, details: dict[str, Any] | None = None):
        self.code = code
        self.message = message
        self.details = details if details is not None else {}
        super().__init__(message)

    def __str__(self) -> str:
        return self.message


_VALID_STATUSES = frozenset({"pending", "leased", "acked", "dead"})

_PUBLIC_FIELDS = frozenset(
    {"message_id", "payload", "status", "available_at", "sequence",
     "attempts", "last_error"}
)

_PRIVATE_FIELDS = frozenset({"worker_id", "lease_token", "expires_at"})

_ALL_MESSAGE_FIELDS = _PUBLIC_FIELDS | _PRIVATE_FIELDS

_TOP_LEVEL_KEYS = frozenset({"schema_version", "next_sequence", "messages"})


def _validate_finite_number(val: Any, name: str) -> float:
    if isinstance(val, bool) or not isinstance(val, (int, float)):
        raise SpoolError("INVALID_INPUT", f"{name} must be a finite number", {})
    if not math.isfinite(val):
        raise SpoolError("INVALID_INPUT", f"{name} must be finite", {})
    return float(val)


def _validate_positive_int(val: Any, name: str) -> int:
    if isinstance(val, bool) or not isinstance(val, int):
        raise SpoolError("INVALID_INPUT", f"{name} must be an integer", {})
    if val <= 0:
        raise SpoolError("INVALID_INPUT", f"{name} must be positive", {})
    return val


def _validate_non_empty_str(val: Any, name: str) -> str:
    if not isinstance(val, str):
        raise SpoolError("INVALID_INPUT", f"{name} must be a string", {})
    if not val.strip():
        raise SpoolError(
            "INVALID_INPUT", f"{name} must be non-empty and non-whitespace", {}
        )
    return val


def _validate_limits(limits: Limits) -> None:
    _validate_positive_int(limits.max_messages, "max_messages")
    _validate_positive_int(limits.max_payload_bytes, "max_payload_bytes")
    _validate_positive_int(limits.max_attempts, "max_attempts")
    _validate_finite_number(limits.lease_seconds, "lease_seconds")
    _validate_finite_number(limits.retry_delay, "retry_delay")
    if limits.lease_seconds <= 0:
        raise SpoolError(
            "INVALID_INPUT", "lease_seconds must be > 0", {}
        )
    if limits.retry_delay < 0:
        raise SpoolError(
            "INVALID_INPUT", "retry_delay must be >= 0", {}
        )


def _canonical_json(obj: Any) -> str:
    return json.dumps(
        obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False,
        allow_nan=False,
    )


def _no_duplicate_keys(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
    seen: set[str] = set()
    result: dict[str, Any] = {}
    for k, v in pairs:
        if k in seen:
            raise ValueError(f"duplicate key: {k}")
        seen.add(k)
        result[k] = v
    return result


def _validate_state(state: dict[str, Any]) -> None:
    if not isinstance(state, dict):
        raise SpoolError("CORRUPT_STATE", "state is not a dict", {})
    top_keys = set(state.keys())
    if not top_keys.issubset(_TOP_LEVEL_KEYS):
        unknown = top_keys - _TOP_LEVEL_KEYS
        raise SpoolError(
            "CORRUPT_STATE", f"unknown top-level keys: {unknown}", {}
        )
    sv = state.get("schema_version")
    if sv != 1:
        raise SpoolError(
            "SCHEMA_MISMATCH",
            f"unknown schema_version: {sv}",
            {},
        )
    nq = state.get("next_sequence")
    if not isinstance(nq, int) or isinstance(nq, bool) or nq < 1:
        raise SpoolError("CORRUPT_STATE", "invalid next_sequence", {})
    msgs = state.get("messages", {})
    if not isinstance(msgs, dict):
        raise SpoolError("CORRUPT_STATE", "messages must be a dict", {})
    for mid, msg in msgs.items():
        if not isinstance(msg, dict):
            raise SpoolError(
                "CORRUPT_STATE", f"message {mid} is not a dict", {}
            )
        msg_keys = set(msg.keys())
        if not msg_keys.issubset(_ALL_MESSAGE_FIELDS):
            unknown = msg_keys - _ALL_MESSAGE_FIELDS
            raise SpoolError(
                "CORRUPT_STATE",
                f"message {mid} has unknown fields: {unknown}",
                {},
            )
        status = msg.get("status")
        if status not in _VALID_STATUSES:
            raise SpoolError(
                "CORRUPT_STATE",
                f"message {mid} has invalid status: {status}",
                {},
            )


def _public_message(msg: dict[str, Any]) -> dict[str, Any]:
    return {k: v for k, v in msg.items() if k in _PUBLIC_FIELDS}


class Spool:
    """Filesystem-backed lease spool."""

    def __init__(
        self,
        root,
        *,
        clock: Callable[[], float],
        limits: Limits,
        lock_timeout: float,
        failpoint: Callable[[str], None] | None,
    ):
        _validate_limits(limits)
        lt = _validate_finite_number(lock_timeout, "lock_timeout")
        if lt < 0:
            raise SpoolError("INVALID_INPUT", "lock_timeout must be >= 0", {})
        self._root = str(root)
        self._clock = clock
        self._limits = limits
        self._lock_timeout = lt
        self._failpoint = failpoint
        self._pid = os.getpid()
        self._state_path = os.path.join(self._root, "state.json")
        self._lock_path = os.path.join(self._root, "state.lock")
        # Track temp files created in current mutation for cleanup
        self._temp_files: list[str] = []

    # ── Lock ──────────────────────────────────────────────────────────

    def _acquire_lock(self) -> None:
        deadline = time.monotonic() + self._lock_timeout
        while True:
            try:
                fd = os.open(
                    self._lock_path,
                    os.O_CREAT | os.O_EXCL | os.O_WRONLY,
                )
                os.write(fd, str(self._pid).encode("utf-8"))
                self._lock_fd = fd
                return
            except FileExistsError:
                if time.monotonic() >= deadline:
                    raise SpoolError(
                        "LOCK_TIMEOUT", "could not acquire lock", {}
                    )
                time.sleep(0.01)

    def _release_lock(self) -> None:
        fd = getattr(self, "_lock_fd", None)
        if fd is not None:
            try:
                os.close(fd)
            except OSError:
                pass
            self._lock_fd = None
        try:
            if os.path.exists(self._lock_path):
                os.remove(self._lock_path)
        except OSError:
            pass

    # ── State I/O ─────────────────────────────────────────────────────

    def _read_state(self) -> dict[str, Any]:
        if not os.path.exists(self._state_path):
            raise SpoolError("NOT_INITIALIZED", "state.json does not exist", {})
        try:
            with open(self._state_path, "r", encoding="utf-8") as f:
                text = f.read()
            if not text.endswith("\n"):
                text = text + "\n"
            state = json.loads(text, object_pairs_hook=_no_duplicate_keys)
        except (json.JSONDecodeError, ValueError, OSError) as exc:
            raise SpoolError(
                "CORRUPT_STATE", f"cannot read state: {exc}", {}
            ) from exc
        _validate_state(state)
        return state

    def _write_state(self, state: dict[str, Any]) -> None:
        text = _canonical_json(state) + "\n"
        # Temp file: .state.<pid>.<unique>.tmp
        unique = os.urandom(4).hex()
        tmp_name = f".state.{self._pid}.{unique}.tmp"
        tmp_path = os.path.join(self._root, tmp_name)
        self._temp_files.append(tmp_path)

        try:
            with open(tmp_path, "w", encoding="utf-8", newline="") as f:
                f.write(text)
                f.flush()
                os.fsync(f.fileno())

            if self._failpoint:
                self._failpoint("before_replace")

            os.replace(tmp_path, self._state_path)

            if self._failpoint:
                self._failpoint("after_replace")

            # fsync root directory where supported
            self._fsync_root()

        except BaseException:
            self._cleanup_temp()
            raise

    def _fsync_root(self) -> None:
        try:
            fd = os.open(self._root, os.O_RDONLY)
            try:
                os.fsync(fd)
            finally:
                os.close(fd)
        except (OSError, AttributeError, NotImplementedError):
            # fsync on directory fd not supported on all platforms (e.g. Windows)
            pass

    def _cleanup_temp(self) -> None:
        for p in self._temp_files:
            try:
                if os.path.exists(p):
                    os.remove(p)
            except OSError:
                pass
        self._temp_files.clear()

    # ── Mutate helper ─────────────────────────────────────────────────

    def _mutate(self, fn: Callable[[dict[str, Any]], None]) -> dict[str, Any]:
        self._acquire_lock()
        try:
            if self._failpoint:
                self._failpoint("after_lock")
            state = self._read_state()
            fn(state)
            self._write_state(state)
        except BaseException:
            self._cleanup_temp()
            self._release_lock()
            raise
        else:
            self._cleanup_temp()
            self._release_lock()

    def _mutate_and_return(
        self, fn: Callable[[dict[str, Any]], Any]
    ) -> Any:
        """Mutate with a return value from the mutation fn."""
        result = None

        def wrapper(state: dict[str, Any]) -> None:
            nonlocal result
            result = fn(state)

        self._mutate(wrapper)
        return result

    # ── Public API ────────────────────────────────────────────────────

    def initialize(self) -> dict:
        """Create root directory and publish initial state atomically."""
        os.makedirs(self._root, exist_ok=True)
        state = {
            "schema_version": 1,
            "next_sequence": 1,
            "messages": {},
        }
        if os.path.exists(self._state_path):
            # Re-read to verify it's valid — not ALREADY_INITIALIZED if readable
            try:
                existing = self._read_state()
                # Already initialized with valid state
                raise SpoolError(
                    "ALREADY_INITIALIZED",
                    "spool already initialized",
                    {},
                )
            except SpoolError as exc:
                if exc.code == "NOT_INITIALIZED":
                    pass  # file exists but empty/corrupt — overwrite? No, fail closed.
                raise

        self._mutate(lambda s: s.update(state))
        return {"root": self._root}

    def enqueue(
        self, message_id: str, payload: Any, available_at: float | None = None
    ) -> dict:
        mid = _validate_non_empty_str(message_id, "message_id")
        # Validate payload serializability and size
        try:
            payload_str = _canonical_json(payload)
        except (ValueError, TypeError) as exc:
            raise SpoolError(
                "INVALID_INPUT", f"payload not JSON-serializable: {exc}", {}
            ) from exc
        payload_bytes = payload_str.encode("utf-8")
        if len(payload_bytes) > self._limits.max_payload_bytes:
            raise SpoolError(
                "INVALID_INPUT",
                f"payload exceeds {self._limits.max_payload_bytes} bytes",
                {},
            )

        def _do_enqueue(state: dict[str, Any]) -> dict:
            msgs = state["messages"]

            # Idempotency check
            if mid in msgs:
                existing = msgs[mid]
                # Compare canonical payload
                existing_payload_str = _canonical_json(existing["payload"])
                req_avail = available_at if available_at is not None else ...
                existing_avail = existing["available_at"]
                if existing_payload_str == payload_str and (
                    req_avail is ... or (
                        isinstance(req_avail, (int, float))
                        and not isinstance(req_avail, bool)
                        and req_avail == existing_avail
                    )
                ):
                    # Idempotent: same payload and numerically equal available_at
                    return _public_message(existing)
                raise SpoolError(
                    "IDEMPOTENCY_CONFLICT",
                    f"message_id {mid} exists with different content",
                    {},
                )

            # Capacity check: max_messages limits total records incl terminal
            if len(msgs) >= self._limits.max_messages:
                raise SpoolError(
                    "CAPACITY_EXCEEDED",
                    f"max messages ({self._limits.max_messages}) reached",
                    {},
                )

            seq = state["next_sequence"]
            state["next_sequence"] = seq + 1

            now = self._clock()
            if isinstance(now, bool) or not isinstance(now, (int, float)):
                raise SpoolError(
                    "INVALID_DEPENDENCY", "clock returned invalid type", {}
                )
            if not math.isfinite(now):
                raise SpoolError(
                    "INVALID_DEPENDENCY",
                    "clock returned non-finite value",
                    {},
                )

            avail = available_at if available_at is not None else now
            if isinstance(avail, bool) or not isinstance(avail, (int, float)):
                raise SpoolError(
                    "INVALID_INPUT",
                    "available_at must be a finite number",
                    {},
                )
            if not math.isfinite(avail):
                raise SpoolError(
                    "INVALID_INPUT", "available_at must be finite", {}
                )

            msg = {
                "message_id": mid,
                "payload": payload,
                "status": "pending",
                "available_at": float(avail),
                "sequence": seq,
                "attempts": 0,
                "last_error": None,
                "worker_id": None,
                "lease_token": None,
                "expires_at": None,
            }
            msgs[mid] = msg
            return _public_message(msg)

        # available_at validation before mutation
        if available_at is not None:
            if isinstance(available_at, bool) or not isinstance(available_at, (int, float)):
                raise SpoolError(
                    "INVALID_INPUT", "available_at must be a finite number", {}
                )
            if not math.isfinite(available_at):
                raise SpoolError(
                    "INVALID_INPUT", "available_at must be finite", {}
                )

        return self._mutate_and_return(_do_enqueue)

    def claim(self, worker_id: str) -> dict | None:
        wid = _validate_non_empty_str(worker_id, "worker_id")

        def _do_claim(state: dict[str, Any]) -> dict | None:
            msgs = state["messages"]
            now = self._clock()
            if isinstance(now, bool) or not isinstance(now, (int, float)):
                raise SpoolError(
                    "INVALID_DEPENDENCY", "clock returned invalid type", {}
                )
            if not math.isfinite(now):
                raise SpoolError(
                    "INVALID_DEPENDENCY",
                    "clock returned non-finite value",
                    {},
                )

            # Find the best candidate: pending, available_at <= now,
            #  minimum (available_at, sequence, message_id)
            candidates = [
                m for m in msgs.values()
                if m["status"] == "pending"
                and m["available_at"] <= now
            ]
            if not candidates:
                return None

            best = min(
                candidates,
                key=lambda m: (m["available_at"], m["sequence"], m["message_id"]),
            )

            # Mark as leased
            best["status"] = "leased"
            best["attempts"] = best["attempts"] + 1
            best["worker_id"] = wid
            best["lease_token"] = os.urandom(16).hex()
            best["expires_at"] = now + self._limits.lease_seconds

            result = _public_message(best)
            result["lease_token"] = best["lease_token"]
            return result

        return self._mutate_and_return(_do_claim)

    def ack(self, message_id: str, lease_token: str) -> dict:
        mid = _validate_non_empty_str(message_id, "message_id")
        tok = _validate_non_empty_str(lease_token, "lease_token")

        def _do_ack(state: dict[str, Any]) -> dict:
            msgs = state["messages"]
            if mid not in msgs:
                raise SpoolError("NOT_FOUND", f"message not found: {mid}", {})
            msg = msgs[mid]
            if msg["status"] != "leased":
                raise SpoolError(
                    "INVALID_STATE",
                    f"message {mid} is not leased (status={msg['status']})",
                    {},
                )
            expected = msg.get("lease_token")
            if expected is None or not hmac.compare_digest(
                tok.encode("utf-8"), expected.encode("utf-8")
            ):
                raise SpoolError(
                    "UNAUTHORIZED", "invalid lease token", {}
                )
            msg["status"] = "acked"
            msg["worker_id"] = None
            msg["lease_token"] = None
            msg["expires_at"] = None
            return _public_message(msg)

        return self._mutate_and_return(_do_ack)

    def fail(self, message_id: str, lease_token: str, error: str) -> dict:
        mid = _validate_non_empty_str(message_id, "message_id")
        tok = _validate_non_empty_str(lease_token, "lease_token")
        if not isinstance(error, str) or not error.strip():
            raise SpoolError(
                "INVALID_INPUT", "error must be a non-empty string", {}
            )

        def _do_fail(state: dict[str, Any]) -> dict:
            msgs = state["messages"]
            if mid not in msgs:
                raise SpoolError("NOT_FOUND", f"message not found: {mid}", {})
            msg = msgs[mid]
            if msg["status"] != "leased":
                raise SpoolError(
                    "INVALID_STATE",
                    f"message {mid} is not leased (status={msg['status']})",
                    {},
                )
            expected = msg.get("lease_token")
            if expected is None or not hmac.compare_digest(
                tok.encode("utf-8"), expected.encode("utf-8")
            ):
                raise SpoolError(
                    "UNAUTHORIZED", "invalid lease token", {}
                )

            now = self._clock()
            if isinstance(now, bool) or not isinstance(now, (int, float)):
                raise SpoolError(
                    "INVALID_DEPENDENCY", "clock returned invalid type", {}
                )
            if not math.isfinite(now):
                raise SpoolError(
                    "INVALID_DEPENDENCY",
                    "clock returned non-finite value",
                    {},
                )

            msg["last_error"] = error
            msg["worker_id"] = None
            msg["lease_token"] = None
            msg["expires_at"] = None

            if msg["attempts"] >= self._limits.max_attempts:
                msg["status"] = "dead"
            else:
                msg["status"] = "pending"
                msg["available_at"] = now + self._limits.retry_delay

            return _public_message(msg)

        return self._mutate_and_return(_do_fail)

    def recover(self) -> dict:
        def _do_recover(state: dict[str, Any]) -> dict:
            msgs = state["messages"]
            now = self._clock()
            if isinstance(now, bool) or not isinstance(now, (int, float)):
                raise SpoolError(
                    "INVALID_DEPENDENCY", "clock returned invalid type", {}
                )
            if not math.isfinite(now):
                raise SpoolError(
                    "INVALID_DEPENDENCY",
                    "clock returned non-finite value",
                    {},
                )

            count = 0
            for msg in msgs.values():
                if msg["status"] == "leased":
                    expires = msg.get("expires_at")
                    if expires is not None and now >= expires:
                        # Recover this lease
                        msg["worker_id"] = None
                        msg["lease_token"] = None
                        msg["expires_at"] = None
                        if msg["attempts"] >= self._limits.max_attempts:
                            msg["status"] = "dead"
                        else:
                            msg["status"] = "pending"
                            msg["available_at"] = now
                        count += 1
            return {"recovered": count}

        return self._mutate_and_return(_do_recover)

    def get(self, message_id: str) -> dict:
        mid = _validate_non_empty_str(message_id, "message_id")

        def _do_get(state: dict[str, Any]) -> dict:
            msgs = state["messages"]
            if mid not in msgs:
                raise SpoolError("NOT_FOUND", f"message not found: {mid}", {})
            return _public_message(msgs[mid])

        return self._mutate_and_return(_do_get)

    def list_messages(self, status: str | None = None) -> list[dict]:
        if status is not None:
            if status not in _VALID_STATUSES:
                raise SpoolError(
                    "INVALID_INPUT",
                    f"invalid status filter: {status}",
                    {},
                )

        def _do_list(state: dict[str, Any]) -> list[dict]:
            msgs = state["messages"]
            candidates = list(msgs.values())
            if status is not None:
                candidates = [m for m in candidates if m["status"] == status]
            candidates.sort(key=lambda m: (m["available_at"], m["sequence"], m["message_id"]))
            return [_public_message(m) for m in candidates]

        return self._mutate_and_return(_do_list)


__all__ = ["Limits", "Spool", "SpoolError"]

