"""Delivery spool JSON CLI entry point.

Usage: python -m src.delivery_spool --root <path> <command>

Commands: init, enqueue, claim, ack, fail, recover, show, list
"""

from __future__ import annotations

import json
import sys
import time

from src.delivery_spool import Limits, Spool, SpoolError


_COMMANDS = frozenset({
    "init", "enqueue", "claim", "ack", "fail", "recover", "show", "list",
})

_NO_INPUT_COMMANDS = frozenset({"init", "recover"})


def _read_input() -> dict:
    line = sys.stdin.readline()
    if not line or not line.strip():
        return {}
    try:
        obj = json.loads(line)
    except json.JSONDecodeError:
        _error_exit("INVALID_INPUT", "invalid JSON on stdin", {})
    if not isinstance(obj, dict):
        _error_exit("INVALID_INPUT", "input must be a JSON object", {})
    return obj


def _success_exit(result) -> None:
    envelope = {"ok": True, "result": result}
    sys.stdout.write(
        json.dumps(envelope, sort_keys=True, separators=(",", ":"), allow_nan=False)
        + "\n"
    )
    sys.stdout.flush()
    sys.exit(0)


def _error_exit(code: str, message: str, details: dict, exit_code: int = 2) -> None:
    envelope = {
        "ok": False,
        "error": {"code": code, "message": message, "details": details},
    }
    sys.stdout.write(
        json.dumps(envelope, sort_keys=True, separators=(",", ":"), allow_nan=False)
        + "\n"
    )
    sys.stdout.flush()
    sys.exit(exit_code)


def main() -> None:
    args = sys.argv[1:]
    if len(args) < 3 or args[0] != "--root":
        _error_exit(
            "INVALID_INPUT",
            "usage: python -m src.delivery_spool --root <path> <command>",
            {},
        )

    root = args[1]
    command = args[2]

    if command not in _COMMANDS:
        _error_exit(
            "INVALID_INPUT",
            f"unknown command: {command}",
            {"valid": sorted(_COMMANDS)},
        )

    if command in _NO_INPUT_COMMANDS:
        inp = {}
    else:
        inp = _read_input()

    spool = Spool(
        root,
        clock=time.time,
        limits=Limits(),
        lock_timeout=10.0,
        failpoint=None,
    )

    try:
        if command == "init":
            result = spool.initialize()
        elif command == "enqueue":
            mid = inp.get("message_id")
            payload = inp.get("payload")
            if mid is None or payload is None:
                _error_exit(
                    "INVALID_INPUT",
                    "enqueue requires message_id and payload",
                    {},
                )
            avail = inp.get("available_at")
            result = spool.enqueue(mid, payload, available_at=avail)
        elif command == "claim":
            wid = inp.get("worker_id")
            if wid is None:
                _error_exit("INVALID_INPUT", "claim requires worker_id", {})
            result = spool.claim(wid)
        elif command == "ack":
            mid = inp.get("message_id")
            tok = inp.get("lease_token")
            if mid is None or tok is None:
                _error_exit(
                    "INVALID_INPUT",
                    "ack requires message_id and lease_token",
                    {},
                )
            result = spool.ack(mid, tok)
        elif command == "fail":
            mid = inp.get("message_id")
            tok = inp.get("lease_token")
            err = inp.get("error")
            if mid is None or tok is None or err is None:
                _error_exit(
                    "INVALID_INPUT",
                    "fail requires message_id, lease_token, and error",
                    {},
                )
            result = spool.fail(mid, tok, err)
        elif command == "recover":
            result = spool.recover()
        elif command == "show":
            mid = inp.get("message_id")
            if mid is None:
                _error_exit("INVALID_INPUT", "show requires message_id", {})
            result = spool.get(mid)
        elif command == "list":
            st = inp.get("status")
            result = spool.list_messages(status=st)
        else:
            _error_exit("INVALID_INPUT", f"unhandled command: {command}", {})
            return
    except SpoolError as exc:
        # Determine exit code based on error type
        if exc.code in (
            "LOCK_TIMEOUT", "CORRUPT_STATE", "INTERNAL_ERROR"
        ):
            exit_code = 3
        elif exc.code == "SCHEMA_MISMATCH":
            exit_code = 3
        else:
            exit_code = 2
        _error_exit(exc.code, exc.message, exc.details, exit_code=exit_code)
    except Exception:
        _error_exit(
            "INTERNAL_ERROR", "unexpected internal failure", {}, exit_code=3,
        )
    else:
        _success_exit(result)


if __name__ == "__main__":
    main()

